module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] cnt;
    reg tick_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= 0;
            tick_reg <= 0;
        end else begin
            if (cnt == (div - 1)) begin
                cnt <= 0;
                tick_reg <= 1;
            end else begin
                cnt <= cnt + 1;
                tick_reg <= 0;
            end
        end
    end

    assign tick = tick_reg;

endmodule

