module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
localparam TxIdle = 0, Sending = 1, TxDone = 2;
	localparam RxIdle = 0, Receiving = 1, RxDone = 2;
	reg [1:0]TxState = TxIdle;
	reg [1:0]RxState = RxIdle;
	reg [8:0]TxData = 0;
	reg [8:0]RxData = 0;
	reg [10:0]TxBdCount = 0;
	reg [10:0]RxBdCount = 0;
	always @(posedge ipClk) begin
		if(ipReset) begin
			TxState <= TxIdle;
			TxData <= 0;
			TxBdCount <= 0;
			opTxBusy <= 0;
			opTx <= 0;
		end else begin
			case (TxState)
				TxIdle: begin
					if(ipTxSend) begin
						TxState <= Sending;
						TxData <= {1'b0,ipTxData,1'b1};
						TxBdCount <= 0;
						opTxBusy <= 1;
					end
				end
				Sending: begin
					if(TxBdCount == 433) begin
						TxBdCount <= 0;
						TxData <= {TxData[7:0],1'b0};
						if(TxData[0]) begin
							TxState <= TxDone;
							opTxBusy <= 0;
						end
					end else begin
						TxBdCount <= TxBdCount + 1;
					end
				end
				TxDone: begin
					TxState <= TxIdle;
				end
			endcase
			case (RxState)
				RxIdle: begin
					if(!ipRx) begin
						RxState <= Receiving;
						RxData <= 0;
						RxBdCount <= 0;
					end
				end
				Receiving: begin
					if(RxBdCount == 433) begin
						RxBdCount <= 0;
						RxData <= {RxData[7:0],ipRx};
						if(RxData[0]) begin
							RxState <= RxDone;
							opRxData <= RxData[7:1];
							opRxValid <= 1;
						end
					end else begin
						RxBdCount <= RxBdCount + 1;
					end
				end
				RxDone: begin
					RxState <= RxIdle;
					opRxValid <= 0;
				end
			endcase
			opTx <= TxData[0];
		end
	end
endmodule

