module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] hsync_pixels=96;
parameter [31:0] hblank_pixels=160;
parameter [31:0] total_lines=480;
parameter [31:0] vsync_lines=2;
parameter [31:0] vblank_lines=33;
  wire [9:0] hcount;
  wire [9:0] vcount;
  wire [9:0] hcount_next;
  wire [9:0] vcount_next;
  assign hcount = hcount_next;
  assign vcount = vcount_next;
  assign hsync = hcount < (total_pixels - hsync_pixels) ? 1'b0 : 1'b1;
  assign vsync = vcount < (total_lines - vsync_lines) ? 1'b0 : 1'b1;
  assign pixel_x = hcount;
  assign pixel_y = vcount;
  assign visible_region = hcount < (total_pixels - hblank_pixels) && vcount < (total_lines - vblank_lines) ? 1'b1 : 1'b0;
  always @(posedge pixel_clk) begin
    if((hcount == (total_pixels - 1))) begin
      hcount_next <= 0;
    end
    else begin
      hcount_next <= hcount + 1;
    end
    if((hcount == (total_pixels - 1) && vcount == (total_lines - 1))) begin
      vcount_next <= 0;
    end
    else if((hcount == (total_pixels - 1))) begin
      vcount_next <= vcount + 1;
    end
    else begin
      vcount_next <= vcount;
    end
  end
endmodule

