module counter
#(
  parameter integer WIDTH=5
 )
 (
  input  wire clk  ,
  input  wire rst  ,
  input  wire load ,
  input  wire enab ,
  input  wire [WIDTH-1:0] cnt_in ,
  output reg  [WIDTH-1:0] cnt_out 
 );
reg [WIDTH-1:0] cnt_tmp;
always @(*) begin
  if (rst) begin
    cnt_tmp = 0;
  end else if (load) begin
    cnt_tmp = cnt_in;
  end else if (enab) begin
    cnt_tmp = cnt_out + 1;
  end else begin
    cnt_tmp = cnt_out;
  end
end
always @(posedge clk) begin
  cnt_out <= cnt_tmp;
end
endmodule

module comparator (output reg [2:0] result, input [15:0] X, Y, input clk);
always @(posedge clk) begin
        if (X[15] != Y[15]) begin
            if (X[15] == 1) result = 3'b100;
            else result = 3'b010;
        end
        else if (X[14:10] != Y[14:10]) begin
            if (X[14:10] > Y[14:10]) result = 3'b100;
            else result = 3'b010;
        end
        else if (X[9:0] != Y[9:0]) begin
            if (X[9:0] > Y[9:0]) result = 3'b100;
            else result = 3'b010;
        end
        else result = 3'b001;
    end
endmodule

