module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [1:0]
  S_0 = 0,
  S_ED_T4 = 1,
  S_4D_T4 = 2,
  S_CB_T4 = 3;
reg [1:0] state;  
reg [7:0] cpu_opcode;  
reg ifetch_d;  
wire ifetch;  
wire ifetch_cancel;  
  assign ifetch = i_m1_n == 1'b0 && i_mreq_n == 1'b0 && i_iorq_n == 1'b1 && i_rfsh_n == 1'b1;
  assign ifetch_cancel = i_m1_n == 1'b0 && i_mreq_n == 1'b0 && i_iorq_n == 1'b0 && i_rfsh_n == 1'b1;
  always @(posedge i_CLK_CPU, posedge i_reset) begin
    if((i_reset == 1'b1)) begin
      state <= S_0;
    end else begin
      case(state)
      S_0 : begin
        if((ifetch == 1'b1)) begin
          state <= S_ED_T4;
        end
        else if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      S_ED_T4 : begin
        if((ifetch == 1'b1)) begin
          state <= S_4D_T4;
        end
        else if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      S_4D_T4 : begin
        if((ifetch == 1'b1)) begin
          state <= S_CB_T4;
        end
        else if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      S_CB_T4 : begin
        if((ifetch == 1'b1)) begin
          state <= S_ED_T4;
        end
        else if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
      end
      default : begin
        state <= S_0;
      end
      endcase
    end
  end
  always @(posedge i_CLK_CPU, posedge i_reset) begin
    if((i_reset == 1'b1)) begin
      ifetch_d <= 1'b0;
      cpu_opcode <= {8{1'b0}};
    end else begin
      if((ifetch == 1'b1)) begin
        ifetch_d <= 1'b1;
        cpu_opcode <= i_cpu_d;
      end
      else if((ifetch_cancel == 1'b1)) begin
        ifetch_d <= 1'b0;
      end
    end
  end
  assign o_reti_decode = ifetch_d == 1'b1 && (cpu_opcode == 8'b11011101 || cpu_opcode == 8'b11001101);
  assign o_reti_seen = ifetch_d == 1'b1 && cpu_opcode == 8'b11011101;
endmodule

