module CAS(
	input [3:0] IN,
	output [3:0] OUT
	);
assign OUT[0] = IN[0] & IN[1] & IN[2] | IN[0] & IN[1] & IN[3] | IN[0] & IN[2] & IN[3] | IN[1] & IN[2] & IN[3];
	assign OUT[1] = IN[0] ^ IN[1] ^ IN[2] ^ IN[3];
	assign OUT[2] = IN[1];
	assign OUT[3] = IN[0];
endmodule

module FIFO_toe_rtTimer2stateTable_releaseStat_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output [DATA_WIDTH-1:0] q;
parameter DATA_WIDTH = 32'd16;
parameter ADDR_WIDTH = 32'd2;
parameter DEPTH = 32'd3;

reg[DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
    begin
        if (ce)
        begin
            for (i=0;i<DEPTH-1;i=i+1)
                SRL_SIG[i+1] <= SRL_SIG[i];
            SRL_SIG[0] <= data;
        end
    end

assign q = SRL_SIG[a];

endmodule

