module clk_div(
input wire clk_i,
output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] count;
  always @(posedge clk_i) begin
    if(count == 2) begin
      count <= {2{1'b0}};
    end
    else begin
      count <= count + 1;
    end
  end
  assign count_o = count;
  assign clk_o = count == 1 || count == 2 ? 1'b1 : 1'b0;
endmodule

