module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;


input [7:0]request_floor; 
input [7:0]in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 



output direction; 
output complete;
output door_alert;
output weight_alert;
output [7:0] out_current_floor;
reg direction; 
reg complete;
reg door_alert;
reg weight_alert;
reg [7:0] out_current_floor;
reg [7:0] current_floor;
reg [7:0] request_floor_reg;

always @(posedge clk) begin
	if (reset) begin
		current_floor <= in_current_floor;
		request_floor_reg <= request_floor;
		direction <= 0;
		complete <= 0;
		door_alert <= 0;
		weight_alert <= 0;
		out_current_floor <= in_current_floor;
	end else begin
		if (over_time || over_weight) begin
			door_alert <= 1;
			weight_alert <= 1;
		end else begin
			if (request_floor_reg > current_floor) begin
				direction <= 1;
				current_floor <= current_floor + 1;
			end else if (request_floor_reg < current_floor) begin
				direction <= 0;
				current_floor <= current_floor - 1;
			end else begin
				direction <= 0;
				complete <= 1;
			end
			door_alert <= 0;
			weight_alert <= 0;
		end
		out_current_floor <= current_floor;
	end
end

endmodule

