module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state;
   reg [35:0] data0_o, data1_o;
   reg src0_rdy_o, src1_rdy_o;
   wire eof = data_i[35];
   wire match = (data_i & match_mask) == match_data;
   assign dst_rdy_o = (state == IDLE) ? 1'b1 : 1'b0;
   always @(posedge clk or posedge reset or posedge clear) begin
      if (reset) begin
         state <= IDLE;
      end else if (clear) begin
         state <= IDLE;
      end else begin
         case (state)
            IDLE: begin
               if (src_rdy_i) begin
                  if (match) begin
                     state <= DATA0;
                  end else begin
                     state <= DATA1;
                  end
               end
            end
            DATA0: begin
               if (src_rdy_i) begin
                  if (eof) begin
                     state <= IDLE;
                  end else begin
                     state <= DATA0;
                  end
               end
            end
            DATA1: begin
               if (src_rdy_i) begin
                  if (eof) begin
                     state <= IDLE;
                  end else begin
                     state <= DATA1;
                  end
               end
            end
         endcase
      end
   end
   always @(posedge clk or posedge reset or posedge clear) begin
      if (reset) begin
         data0_o <= 36'h0;
         data1_o <= 36'h0;
         src0_rdy_o <= 1'b0;
         src1_rdy_o <= 1'b0;
      end else if (clear) begin
         data0_o <= 36'h0;
         data1_o <= 36'h0;
         src0_rdy_o <= 1'b0;
         src1_rdy_o <= 1'b0;
      end else begin
         case (state)
            IDLE: begin
               data0_o <= 36'h0;
               data1_o <= 36'h0;
               src0_rdy_o <= 1'b0;
               src1_rdy_o <= 1'b0;
            end
            DATA0: begin
               data0_o <= data_i;
               data1_o <= 36'h0;
               src0_rdy_o <= 1'b1;
               src1_rdy_o <= 1'b0;
            end
            DATA1: begin
               data0_o <= 36'h0;
               data1_o <= data_i;
               src0_rdy_o <= 1'b0;
               src1_rdy_o <= 1'b1;
            end
         endcase
      end
   end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			3'b000:	jmpb = (data_rs1 == data_rs2);
			3'b001:	jmpb = (data_rs1 != data_rs2);
			3'b010:	jmpb = (data_rs1 < data_rs2);
			3'b011:	jmpb = (data_rs1 >= data_rs2);
			3'b100:	jmpb = (data_rs1 < data_rs2) ^ (data_rs1[31] ^ data_rs2[31]);
			3'b101:	jmpb = (data_rs1 >= data_rs2) ^ (data_rs1[31] ^ data_rs2[31]);
			default:	jmpb = 0;
		endcase
	end
endmodule

