        if(dig[9]) uni <= 4'b1001;
        else if(dig[8]) uni <= 4'b1000;
        else if(dig[7]) uni <= 4'b0111;
        else if(dig[6]) uni <= 4'b0110;
        else if(dig[5]) uni <= 4'b0101;
        else if(dig[4]) uni <= 4'b0100;
        else if(dig[3]) uni <= 4'b0011;
        else if(dig[2]) uni <= 4'b0010;
        else if(dig[1]) uni <= 4'b0001;
        else if(dig[0]) uni <= 4'b0000;
    end
end
endmodule

