module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0;
reg [AW-1:0] cached_addr1;
reg [DW-1:0] cached_data0;
reg [DW-1:0] cached_data1;
reg [1:0] subaddr;
reg good;

always @(addr or DW) begin
    addr_req = addr;
    if (DW == 8) addr_req = {addr_req[17:0], 2'b00};
    else if (DW == 16) addr_req = {addr_req[17:0], 1'b0};
end

wire hit0 = (addr_req == cached_addr0);
wire hit1 = (addr_req == cached_addr1);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        req <= 0;
        data_ok <= 0;
        good <= 0;
    end else if (clr) begin
        req <= 0;
        data_ok <= 0;
        good <= 0;
    end else begin
        if (addr_ok && !good) begin
            req <= 1;
            data_ok <= 0;
            good <= 1;
        end else if (addr_ok && good) begin
            req <= 0;
            data_ok <= 1;
        end else begin
            req <= 0;
            data_ok <= 0;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        cached_addr0 <= 0;
        cached_addr1 <= 0;
        cached_data0 <= 0;
        cached_data1 <= 0;
    end else if (clr) begin
        cached_addr0 <= 0;
        cached_addr1 <= 0;
        cached_data0 <= 0;
        cached_data1 <= 0;
    end else begin
        if (we && addr_ok && good) begin
            if (hit0) begin
                cached_data0 <= din;
            end else if (hit1) begin
                cached_data1 <= din;
            end else begin
                if (good) begin
                    cached_addr1 <= cached_addr0;
                    cached_data1 <= cached_data0;
                end
                cached_addr0 <= addr_req;
                cached_data0 <= din;
            end
        end
    end
end

always @(addr_req or DW) begin
    sdram_addr = addr_req;
    if (DW == 8) sdram_addr = {sdram_addr[17:0], 2'b00};
    else if (DW == 16) sdram_addr = {sdram_addr[17:0], 1'b0};
    sdram_addr = sdram_addr + offset;
end

always @(addr_req or DW) begin
    subaddr = addr_req[DW-1:DW-2];
    if (DW == 8) subaddr = addr_req[1:0];
    if (DW == 16) subaddr = addr_req[1];
end

always @(addr_req or DW or din or din_ok or hit0 or hit1) begin
    if (addr_ok && good) begin
        if (hit0) begin
            dout = cached_data0;
        end else if (hit1) begin
            dout = cached_data1;
        end else begin
            dout = din;
        end
    end else begin
        dout = 0;
    end
end

endmodule

