module buart #(
  parameter FREQ_MHZ = 2,
  parameter BAUDS    = 115200	       
) (
    input clk,
    input resetq,
    output tx,
    input  rx,
    input  wr,
    input  rd,
    input  [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output valid
);
localparam DIV = (FREQ_MHZ * 1000000) / (BAUDS * 8);
  reg [3:0] recv_divcnt;
  reg [7:0] recv_pattern;
  reg recv_buf_valid;
  reg [7:0] recv_buf_data;
  reg recv_state;
  reg [2:0] recv_cnt;
  reg [7:0] recv_data;
  reg [3:0] send_divcnt;
  reg [7:0] send_pattern;
  reg send_state;
  reg [2:0] send_cnt;
  reg [7:0] send_data;
  reg send_busy;
  reg [7:0] tx_data_reg;
  reg tx;
  always @(posedge clk) begin
    if (resetq) begin
      recv_divcnt <= 0;
      recv_state <= 0;
      recv_cnt <= 0;
      recv_buf_valid <= 0;
      recv_buf_data <= 0;
      send_divcnt <= 0;
      send_state <= 0;
      send_cnt <= 0;
      send_busy <= 0;
      send_data <= 0;
      tx_data_reg <= 0;
      tx <= 1;
    end else begin
      if (recv_state == 0) begin
        if (rx == 0) begin
          recv_state <= 1;
          recv_cnt <= 0;
          recv_divcnt <= 0;
        end
      end else begin
        if (recv_divcnt == DIV) begin
          recv_divcnt <= 0;
          recv_cnt <= recv_cnt + 1;
          if (recv_cnt == 7) begin
            recv_buf_data <= recv_pattern;
            recv_buf_valid <= 1;
            recv_state <= 0;
          end else begin
            recv_pattern <= {rx, recv_pattern[7:1]};
          end
        end else begin
          recv_divcnt <= recv_divcnt + 1;
        end
      end
      if (send_state == 0) begin
        if (wr) begin
          send_state <= 1;
          send_cnt <= 0;
          send_divcnt <= 0;
          send_data <= tx_data;
        end
      end else begin
        if (send_divcnt == DIV) begin
          send_divcnt <= 0;
          send_cnt <= send_cnt + 1;
          if (send_cnt == 7) begin
            send_state <= 0;
            send_busy <= 0;
          end else begin
            tx <= send_data[send_cnt];
          end
        end else begin
          send_divcnt <= send_divcnt + 1;
        end
      end
      if (rd) begin
        send_busy <= 1;
      end
      tx_data_reg <= tx_data;
    end
  end
  assign rx_data = recv_buf_data;
  assign valid = recv_buf_valid;
  assign busy = send_busy;
endmodule

