module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] data;
reg [2:0] next_data;
reg [2:0] next_ctrl;
reg [2:0] ctrl;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= {3{1'b0}};
      ctrl <= {3{1'b0}};
    end else begin
      data <= next_data;
      ctrl <= next_ctrl;
    end
  end
  always @(data, ctrl, D, A, WR, RD) begin
    next_data <= data;
    next_ctrl <= ctrl;
    if((WR == 1'b1)) begin
      next_data <= D;
      next_ctrl <= A;
    end
    if((RD == 1'b1)) begin
      next_data <= data;
      next_ctrl <= A;
    end
  end
  always @(data, ctrl) begin
    Y <= {7{1'b0}};
    Y[ctrl] <= 1'b1;
  end
  assign WCTRL = ctrl[2];
endmodule

