parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_BACK_PORCH=45;
parameter [31:0] V_TOTAL=798;
reg [10:0] X_reg = 0;
reg [10:0] Y_reg = 0;
reg H_SYNC_reg = 1'b1;
reg V_SYNC_reg = 1'b1;
reg DISP_EN_reg = 1'b0;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      X_reg <= 0;
      Y_reg <= 0;
      H_SYNC_reg <= 1'b1;
      V_SYNC_reg <= 1'b1;
      DISP_EN_reg <= 1'b0;
    end else begin
      if((X_reg == (H_ACTIVE - 1))) begin
        X_reg <= 0;
        if((Y_reg == (V_ACTIVE - 1))) begin
          Y_reg <= 0;
          if((H_SYNC_reg == 1'b0)) begin
            H_SYNC_reg <= 1'b1;
          end
          else if((V_SYNC_reg == 1'b0)) begin
            V_SYNC_reg <= 1'b1;
          end
          else begin
            V_SYNC_reg <= 1'b0;
          end
        end
        else begin
          Y_reg <= Y_reg + 1;
          if((H_SYNC_reg == 1'b0)) begin
            H_SYNC_reg <= 1'b1;
          end
          else begin
            H_SYNC_reg <= 1'b0;
          end
        end
      end
