        X_reg <= X_reg + 1;
        if((H_SYNC_reg == 1'b0)) begin
          H_SYNC_reg <= 1'b1;
        end
        else begin
          H_SYNC_reg <= 1'b0;
        end
      end
      if((X_reg < H_ACTIVE)) begin
        if((Y_reg < V_ACTIVE)) begin
          DISP_EN_reg <= 1'b1;
        end
        else begin
          DISP_EN_reg <= 1'b0;
        end
      end
      else begin
        DISP_EN_reg <= 1'b0;
      end
    end
  end
  assign H_SYNC = H_SYNC_reg;
  assign V_SYNC = V_SYNC_reg;
  assign DISP_EN = DISP_EN_reg;
  assign X = X_reg;
  assign Y = Y_reg;
endmodule

