module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    reg scan_ready_reg;
    always @(posedge reset or negedge i_clock) begin
        if (reset) begin
            scan_code <= 0;
            counter <= 0;
            scan_ready_reg <= 0;
        end else begin
            if (counter == 0) begin
                scan_ready_reg <= 0;
            end
            if (counter == 8) begin
                if (i_data == scan_code[7] ^ scan_code[6] ^ scan_code[5] ^ scan_code[4] ^ scan_code[3] ^ scan_code[2] ^ scan_code[1] ^ scan_code[0]) begin
                    scan_ready_reg <= 1;
                end
            end
            if (counter == 9) begin
                if (i_data == 1) begin
                    scan_ready_reg <= 0;
                end
            end
            if (counter == 10) begin
                scan_code <= scan_code << 1;
                scan_code[0] <= i_data;
                counter <= 0;
            end
            if (counter < 10) begin
                counter <= counter + 1;
            end
        end
    end
    assign scan_ready = scan_ready_reg;
    assign scan_code = scan_code;
endmodule

