	  4'b1000: alu_result_int = alu_src1 + alu_src2;
	  4'b1001: alu_result_int = alu_src1 - alu_src2;
	  4'b1010: alu_result_int = alu_src1 | alu_src2;
	  4'b1011: alu_result_int = alu_src1 & alu_src2;
