module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
generate
        if (ASYNC == 0) begin
            reg [DATA_WIDTH-1:0] dout_reg;
            always @(posedge clk) begin
                dout_reg <= din << SHIFT_VALUE;
            end
            assign dout = dout_reg;
        end else begin
            wire [DATA_WIDTH-1:0] dout_wire;
            assign dout_wire = din << SHIFT_VALUE;
            assign dout = dout_wire;
        end
    endgenerate

    generate
        if (DATA_TYPE == "signed") begin
            wire [DATA_WIDTH-1:0] dout_wire;
            assign dout_wire = din << SHIFT_VALUE;
            wire [DATA_WIDTH-1:0] overflow;
            assign overflow = (dout_wire > 2**(DATA_WIDTH-1)) | (dout_wire < -(2**(DATA_WIDTH-1)));
            generate
                if (OVERFLOW_WARNING == 1) begin
                    wire [1:0] warning_wire;
                    assign warning_wire = overflow ? 2'b11 : 2'b00;
                    assign warning = warning_wire;
                end else begin
                    assign warning = 2'b00;
                end
            endgenerate
        end else begin
            wire [DATA_WIDTH-1:0] dout_wire;
            assign dout_wire = din << SHIFT_VALUE;
            wire [DATA_WIDTH-1:0] overflow;
            assign overflow = (dout_wire > 2**(DATA_WIDTH-1));
            generate
                if (OVERFLOW_WARNING == 1) begin
                    wire [1:0] warning_wire;
                    assign warning_wire = overflow ? 2'b11 : 2'b00;
                    assign warning = warning_wire;
                end else begin
                    assign warning = 2'b00;
                end
            endgenerate
        end
    endgenerate

endmodule

