module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;
parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b0110;

parameter OVERFLOW = 1'b1;
parameter NO_OVERFLOW = 1'b0;
parameter INVALID_CONTROL = 1'b1;
parameter VALID_CONTROL = 1'b0;

always @(*) begin
  case (control)
    AND: begin
      result = input_a & input_b;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    OR: begin
      result = input_a | input_b;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    ADD: begin
      result = input_a + input_b;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    ADD_UNSIGNED: begin
      result = input_a + input_b;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    SUB: begin
      result = input_a - input_b;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    SLT: begin
      result = input_a < input_b ? 1 : 0;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    NOR: begin
      result = ~(input_a | input_b);
      err_overflow = NO_OVERFLOW;
      err_invalid_control = VALID_CONTROL;
    end
    default: begin
      result = 0;
      err_overflow = NO_OVERFLOW;
      err_invalid_control = INVALID_CONTROL;
    end
  endcase
end

assign zero = result == 0 ? 1'b1 : 1'b0;

endmodule

