module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [1:0] cnt;
    always @(posedge clk or posedge reset)
    begin
        if(reset)
            cnt <= 0;
        else
            cnt <= cnt + 1;
    end
    always @(cnt)
    begin
        case(cnt)
            0: begin
                en <= 4'b1110;
                sseg <= hex0;
            end
            1: begin
                en <= 4'b1101;
                sseg <= hex1;
            end
            2: begin
                en <= 4'b1011;
                sseg <= hex2;
            end
            3: begin
                en <= 4'b0111;
                sseg <= hex3;
            end
        endcase
    end
    always @(sseg,dp)
    begin
        case(sseg)
            0: sseg <= 7'b1000000;
            1: sseg <= 7'b1111001;
            2: sseg <= 7'b0100100;
            3: sseg <= 7'b0110000;
            4: sseg <= 7'b0011001;
            5: sseg <= 7'b0010010;
            6: sseg <= 7'b0000010;
            7: sseg <= 7'b1111000;
            8: sseg <= 7'b0000000;
            9: sseg <= 7'b0010000;
            10: sseg <= 7'b0001000;
            11: sseg <= 7'b0000011;
            12: sseg <= 7'b1000110;
            13: sseg <= 7'b0100001;
            14: sseg <= 7'b0000110;
            15: sseg <= 7'b0001110;
        endcase
        sseg[7] <= dp[cnt];
    end
endmodule

