module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires[0] = ena;
    assign out = cnt;
    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : gen_counter
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1;
                    end else begin
                        cnt[i] <= cnt[i] - 1;
                    end
                end
            end
            assign enable_wires[i + 1] = enable_wires[i] & (cnt[i] == 0);
        end
    endgenerate
    assign ovf = cnt[BITS - 1];
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] bcd = 0;
	assign b = bcd[3:0];
	assign s = bcd[7:4];
	assign g = bcd[11:8];
	assign q = bcd[15:12];
	integer i;
	always @ (binary)
	begin
		for (i = 0; i < 16; i = i + 1)
		begin
			if (bcd[3:0] > 4)
				bcd[3:0] = bcd[3:0] + 3;
			if (bcd[7:4] > 4)
				bcd[7:4] = bcd[7:4] + 3;
			if (bcd[11:8] > 4)
				bcd[11:8] = bcd[11:8] + 3;
			if (bcd[15:12] > 4)
				bcd[15:12] = bcd[15:12] + 3;
			bcd = bcd >> 4;
		end
	end
endmodule

