module wb_bridge_16_32
  #(parameter AWIDTH=16)
    (input wb_clk, input wb_rst,
     input A_cyc_i, input A_stb_i, input A_we_i, input [3:0] A_sel_i,
     input [AWIDTH-1:0] A_adr_i, input [31:0] A_dat_i, output [31:0] A_dat_o, output A_ack_o,
     output B_cyc_o, output B_stb_o, output B_we_o, output [1:0] B_sel_o,
     output [AWIDTH-1:0] B_adr_o, output [15:0] B_dat_o, input [15:0] B_dat_i, input B_ack_i
     );
reg [1:0] phase;
    reg [15:0] data;
    reg [15:0] data_o;
    reg ack_o;
    reg [AWIDTH-1:0] adr_o;
    reg [1:0] sel_o;
    reg we_o;
    reg stb_o;
    reg cyc_o;
    always @(posedge wb_clk or posedge wb_rst) begin
        if (wb_rst) begin
            phase <= 0;
            data <= 0;
            data_o <= 0;
            ack_o <= 0;
            adr_o <= 0;
            sel_o <= 0;
            we_o <= 0;
            stb_o <= 0;
            cyc_o <= 0;
        end else begin
            if (A_cyc_i && A_stb_i) begin
                if (phase == 0) begin
                    data <= A_dat_i[15:0];
                    adr_o <= A_adr_i;
                    sel_o <= A_sel_i[1:0];
                    we_o <= A_we_i;
                    stb_o <= 1;
                    cyc_o <= 1;
                    phase <= 1;
                end else begin
                    data <= A_dat_i[31:16];
                    sel_o <= A_sel_i[3:2];
                    stb_o <= 1;
                    cyc_o <= 1;
                    phase <= 0;
                end
            end else begin
                stb_o <= 0;
                cyc_o <= 0;
            end
            if (B_ack_i) begin
                ack_o <= 1;
                if (phase == 0) begin
                    data_o <= {B_dat_i, data};
                end else begin
                    data_o <= {data, B_dat_i};
                end
            end else begin
                ack_o <= 0;
            end
        end
    end
    assign A_dat_o = data_o;
    assign A_ack_o = ack_o;
    assign B_cyc_o = cyc_o;
    assign B_stb_o = stb_o;
    assign B_we_o = we_o;
    assign B_adr_o = adr_o;
    assign B_dat_o = data;
endmodule

