module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg updateclk_tmp;
reg capture_tmp;
reg mainclk_tmp;
reg update_tmp;

wire clk_tmp;
wire shiftnld_tmp;
wire captnupdt_tmp;

and (mainclk, mainclk_tmp, clk_tmp);
and (updateclk, updateclk_tmp, clk_tmp);
and (capture, capture_tmp, clk_tmp);
and (update, update_tmp, clk_tmp);

initial
begin
    updateclk_tmp = 1'b0;
    capture_tmp = 1'b0;
    mainclk_tmp = 1'b0;
    update_tmp = 1'b0;
end

always @(captnupdt or shiftnld or clk)
begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11:
        begin
            updateclk_tmp = clk;
            capture_tmp = 1'b1;
            mainclk_tmp = 1'b0;
            update_tmp = 1'b0;
        end
        2'b01:
        begin
            updateclk_tmp = clk;
            capture_tmp = 1'b0;
            mainclk_tmp = 1'b0;
            update_tmp = 1'b0;
        end
        default:
        begin
            updateclk_tmp = 1'b0;
            capture_tmp = 1'b0;
            mainclk_tmp = clk;
            update_tmp = 1'b1;
        end
    endcase
end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;
    reg [15:0] V_cnt_d;
    reg [15:0] H_cnt_d;
    reg Pout_de_w_d;
    reg Pout_hs_w_d;
    reg Pout_vs_w_d;
    reg Rden_w_d;
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
        end else begin
            if (V_cnt == I_v_total) begin
                V_cnt <= 0;
                H_cnt <= H_cnt + 1;
            end else begin
                V_cnt <= V_cnt + 1;
                H_cnt <= H_cnt;
            end
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            Pout_de_w <= 0;
            Pout_hs_w <= 0;
            Pout_vs_w <= 0;
            Rden_w <= 0;
        end else begin
            if (H_cnt == I_h_total) begin
                Pout_de_w <= 0;
                Pout_hs_w <= 0;
                Pout_vs_w <= 0;
                Rden_w <= 0;
            end else begin
                if (V_cnt == I_v_res) begin
                    Pout_de_w <= 1;
                end
                if (V_cnt == I_v_sync) begin
                    Pout_vs_w <= 1;
                end
                if (V_cnt == I_v_bporch) begin
                    Pout_vs_w <= 0;
                end
                if (H_cnt == I_h_res) begin
                    Pout_hs_w <= 1;
                end
                if (H_cnt == I_h_sync) begin
                    Pout_hs_w <= 0;
                end
                if (H_cnt == I_h_total) begin
                    Rden_w <= 1;
                end
            end
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt_d <= 0;
            H_cnt_d <= 0;
            Pout_de_w_d <= 0;
            Pout_hs_w_d <= 0;
            Pout_vs_w_d <= 0;
            Rden_w_d <= 0;
        end else begin
            V_cnt_d <= V_cnt;
            H_cnt_d <= H_cnt;
            Pout_de_w_d <= Pout_de_w;
            Pout_hs_w_d <= Pout_hs_w;
            Pout_vs_w_d <= Pout_vs_w;
            Rden_w_d <= Rden_w;
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_rden <= 0;
            O_de <= 0;
            O_hs <= 0;
            O_vs <= 0;
        end else begin
            O_rden <= Rden_w_d;
            O_de <= Pout_de_w_d;
            O_hs <= Pout_hs_w_d;
            O_vs <= Pout_vs_w_d;
        end
    end
endmodule

module arriaii_first_stage_add_sub(
                                 dataa,
                                 datab,
                                 sign,
                                 operation,
                                 dataout
                                );


input [71  : 0 ] dataa;
input [71 : 0 ] datab;
input sign;
input [3:0] operation;


output [71: 0] dataout;
parameter dataa_width = 36;
parameter datab_width = 36;
parameter fsa_mode = "add";

reg [71: 0] dataout_tmp;
reg [35: 0] abs_b;
reg [35: 0] abs_a;
reg sign_a;
reg sign_b;

wire [35:0] dataa_signed;
wire [35:0] datab_signed;

assign dataa_signed = dataa[71:36];
assign datab_signed = datab[71:36];

always @ (dataa or datab or sign or operation)
begin
    if (operation == 4'b0000)
    begin
        if (sign == 1'b1)
        begin
            sign_a = dataa[71];
            sign_b = datab[71];
            if (sign_a == 1'b0)
            begin
                abs_a = dataa[71:36];
            end
            else
            begin
                abs_a = 36'b0 - dataa[71:36];
            end
            if (sign_b == 1'b0)
            begin
                abs_b = datab[71:36];
            end
            else
            begin
                abs_b = 36'b0 - datab[71:36];
            end
            dataout_tmp = abs_a + abs_b;
