input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
reg [SIZE-1:0]toggle;

assign gray_out = state[N-1:0];

always @(posedge clk or posedge reset) begin
	if (reset) begin
		state <= Zeros;
	end else if (enable) begin
		state[SIZE-1] <= state[SIZE-1] ^ toggle[SIZE-1];
		state[SIZE-2:0] <= state[SIZE-2:0] ^ toggle[SIZE-2:0];
	end
end

always @(state) begin
	toggle[0] <= 1'b1;
	toggle[SIZE-1] <= state[SIZE-1] ^ state[SIZE-2];
	toggle[SIZE-2:1] <= state[SIZE-2:1] ^ state[SIZE-3:0] ^ state[SIZE-2:1] ^ state[SIZE-1:2];
end

endmodule

