module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0] last_number = 8'b00000000;
    reg [7:0] last_last_number = 8'b00000000;
    reg [7:0] end_number = 8'b00000000;
    reg [7:0] sequence = 8'b00000000;
    always @(posedge CLK_IN or negedge RST_N)
    begin
        if (!RST_N)
        begin
            last_number <= 8'b00000000;
            last_last_number <= 8'b00000000;
            end_number <= 8'b00000000;
            sequence <= 8'b00000000;
        end
        else
        begin
            if (sequence == end_number)
            begin
                last_number <= 8'b00000000;
                last_last_number <= 8'b00000000;
                end_number <= 8'b00000000;
                sequence <= 8'b00000000;
            end
            else
            begin
                sequence <= last_number + last_last_number;
                last_last_number <= last_number;
                last_number <= sequence;
            end
        end
    end
    assign SEQUENCE = sequence;
endmodule

