   		   input clk,
   		   input rst_n,
   		   input [4:0] req,
   		   output [4:0] grant
   		   );
reg [2:0] state;
   reg [4:0] grant;
   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
	 state <= 3'b000;
	 grant <= 5'b00000;
      end else begin
	 if (req[0] && !grant[0]) begin
	    state <= 3'b001;
	    grant <= 5'b00001;
	 end else if (req[1] && !grant[1]) begin
	    state <= 3'b010;
	    grant <= 5'b00010;
	 end else if (req[2] && !grant[2]) begin
	    state <= 3'b100;
	    grant <= 5'b00100;
	 end else if (req[3] && !grant[3]) begin
	    state <= 3'b000;
	    grant <= 5'b01000;
	 end else if (req[4] && !grant[4]) begin
	    state <= 3'b000;
	    grant <= 5'b10000;
	 end else begin
	    state <= 3'b000;
	    grant <= 5'b00000;
	 end
      end
   end
endmodule

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

