	begin
		if(!rst_n)
		begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_out <= 0;
			data_ok <= 0;
		end
		else
		begin
			if(data_in_sign)
			begin
				data_reg <= data_reg + data_in;
			end
