module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam
    DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [$clog2(DEPTH)-1:0] index = 0;

assign empty_n = !index;
assign full_n  = index != DEPTH-1;
assign dout    = mem[index];

generate
    genvar i;
    for (i = 0; i < DEPTH; i = i + 1) begin : gen_sr
        udpAppMux_txLengthNetwork_sr #(
            .DATA_BITS(DATA_BITS)
        ) sr (
            .clk    (clk),
            .aclr   (aclr),
            .dout   (mem[i]),
            .din    (mem[i-1]),
            .enable (i != 0)
        );
    end
endgenerate

always @(posedge clk or posedge aclr) begin
    if (aclr)
        index <= 0;
    else if (write && full_n)
        index <= index + 1;
