module sr_latch(in, out, clk, set, reset);
	input [WIDTH-1:0] in;
	output reg [WIDTH-1:0] out;
	input clk, set, reset;
parameter WIDTH = 8;
	initial begin
		out = 0;
	end
	always @(posedge clk) begin
		if (set)
			out <= in;
		else if (reset)
			out <= 0;
	end
endmodule

