module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	always @(posedge clk) begin
		if(start) begin
			state <= 3'b000;
		end else begin
			if(state[1:0] == 2'b00) begin
				state <= state;
			end else begin
				state <= state + 1;
			end
		end
	end
	assign direction = state[2] ? 4'b0001 : state[1] ? 4'b0010 : state[0] ? 4'b0100 : 4'b1000;
	assign ready = state[2] ? 1'b0 : state[1] ? 1'b0 : state[0] ? 1'b0 : 1'b1;
endmodule

