module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

reg [31:0] len_raw;
reg [31:0] len;
reg [31:0] x_mask;
reg [31:0] f_masked;
reg [31:0] incr;
reg [31:0] f_out;
reg [31:0] res;
  always @(posedge clk) begin
    len_raw <= f[30:23] - 255;
    if((f[30:23] == 0)) begin
      len <= 0;
    end
    else if((f[30:23] == 255)) begin
      len <= 255;
    end
    else begin
      len <= len_raw;
    end
    x_mask <= {1'b0,f[30:23],1'b1};
    f_masked <= f & (x_mask - 1);
    incr <= f_masked + 1;
    f_out <= f[31] == 1'b1 ? f_masked : incr;
    res <= {f[31],f[30:23],f_out[22:0]};
    g <= res;
  end
endmodule

