module ALU(
    output [31:0] ALU_o,
    input signed  [31:0] A, B,
    input  [3:0]  ALUSel
);
wire [31:0] SLL_o, SRL_o, SRA_o, XOR_o, AND_o, OR_o, SLT_o;
    wire [31:0] B_comp;
    assign B_comp = ALUSel[3] ? ~B : B;
    assign ALU_o = {32{1'b0}};
    assign ALU_o[31:0] = ALUSel[2:0] == 3'b000 ? SLL_o[31:0] : ALUSel[2:0] == 3'b001 ? SRL_o[31:0] : ALUSel[2:0] == 3'b010 ? SRA_o[31:0] : ALUSel[2:0] == 3'b011 ? XOR_o[31:0] : ALUSel[2:0] == 3'b100 ? AND_o[31:0] : ALUSel[2:0] == 3'b101 ? OR_o[31:0] : ALUSel[2:0] == 3'b110 ? SLT_o[31:0] : ALU_o[31:0];
    COMP32b COMP32b_inst(.A(A), .B(B_comp), .SLT_o(SLT_o));
    assign SLL_o = A << B[4:0];
    assign SRL_o = A >> B[4:0];
    assign SRA_o = A >>> B[4:0];
    assign XOR_o = A ^ B_comp;
    assign AND_o = A & B_comp;
    assign OR_o = A | B_comp;
endmodule

module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [MAX_COUNT-1:0] comp = MAX_COUNT - 1;
    reg [MAX_COUNT-1:0] count = 0;
    assign pulse = (count == 0) & button;
    always @(posedge clk) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
        end else if (clk_en) begin
            if (button) begin
                count <= count + 1;
                if (count == 0) begin
                    comp <= comp - DEC_COUNT;
                    if (comp < MIN_COUNT) begin
                        comp <= MIN_COUNT;
                    end
                end
            end else begin
                count <= 0;
                comp <= MAX_COUNT - 1;
            end
        end
    end
endmodule

