    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;

    reg [2:0] state, next;

    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S1;
        end else begin
            state <= next;
        end
    end

    always @ (*) begin
        case (state)
            S1: next = x ? S2 : S1;
            S2: next = x ? S3 : S1;
            S3: next = x ? S4 : S1;
            S4: next = x ? S5 : S1;
            S5: next = x ? S6 : S1;
            S6: next = x ? S6 : S1;
            default: next = S1;
        endcase
    end

    assign z = (state == S6) ? 1'b1 : 1'b0;
endmodule

