module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH-1:0]wrptr;
reg [clog2_FIFO_DEPTH-1:0]rdptr;
reg [clog2_FIFO_DEPTH-1:0]wrptr_phase;
reg [clog2_FIFO_DEPTH-1:0]rdptr_phase;
reg [DATA_WIDTH-1:0]fifo [0:FIFO_DEPTH-1];

wire wrreq_en = wrreq & ~full;
wire rdreq_en = rdreq & ~empty;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
        wrptr_phase <= 0;
        rdptr_phase <= 0;
    end
    else
    begin
        if(wrreq_en)
        begin
            wrptr <= wrptr + 1;
            wrptr_phase <= ~wrptr_phase;
        end
        if(rdreq_en)
        begin
            rdptr <= rdptr + 1;
            rdptr_phase <= ~rdptr_phase;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        usedw <= 0;
    end
    else
    begin
        if(wrreq_en)
        begin
            if(rdreq_en)
            begin
                usedw <= usedw;
            end
            else
            begin
                usedw <= usedw + 1;
            end
        end
        else
        begin
            if(rdreq_en)
            begin
                usedw <= usedw - 1;
            end
            else
            begin
                usedw <= usedw;
            end
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        fifo[0] <= 0;
    end
    else
    begin
        if(wrreq_en)
        begin
            fifo[wrptr] <= data_in;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        data_out <= 0;
    end
    else
    begin
        if(rdreq_en)
        begin
            data_out <= fifo[rdptr];
        end
    end
end

assign empty = (usedw == 0);
assign full = (usedw == FIFO_DEPTH);
assign usedw = (wrptr_phase == rdptr_phase) ? wrptr - rdptr : wrptr + (FIFO_DEPTH - rdptr);

endmodule

