module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000000;
  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_w_d;
  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= SEED;
    end else if (next) begin
      M_x <= M_y ^ (M_y >> 2);
      M_y <= M_z ^ (M_z << 1);
      M_z <= M_x ^ (M_x << 3);
      M_w <= M_w ^ (M_w >> 1);
    end
  end
  always @(posedge clk) begin
    if (rst) begin
      M_w_d <= 32'h00000000;
    end else begin
      M_w_d <= M_w;
    end
  end
  always @(posedge clk) begin
    if (rst) begin
      num <= SEED;
    end else begin
      num <= M_w_d;
    end
  end
endmodule

