module soundcodec(
	input	clk,
   input pulse,
   output o_pwm
);
reg [8:0] PWM_accumulator;
   reg [1:0] state;
   always @(posedge clk) begin
      case (state)
         0: begin
            if (pulse) PWM_accumulator <= PWM_accumulator + 8'b11111111;
            state <= 1;
         end
         1: begin
            state <= 0;
         end
      endcase
   end
   assign o_pwm = PWM_accumulator[8];
endmodule

