module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
localparam BAUD = 9600;
    localparam CLK_FREQ = 100000000;
    localparam BIT_PERIOD = CLK_FREQ / BAUD;
    localparam BIT_COUNT = 8;
    localparam PARITY_BIT = 1;
    localparam STOP_BIT = 1;
    localparam TOTAL_BITS = BIT_COUNT + PARITY_BIT + STOP_BIT;
    localparam IDLE = 0;
    localparam START_BIT = 1;
    localparam DATA_BITS = 2;
    localparam PARITY_BIT = 3;
    localparam STOP_BIT = 4;
    localparam DONE = 5;
    reg [2:0] state;
    reg [3:0] bit_counter;
    reg [7:0] data_reg;
    reg parity;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_counter <= 0;
            data_reg <= 0;
            parity <= 0;
            data_out <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START_BIT;
                        bit_counter <= 0;
                        data_reg <= data_in;
                        parity <= 0;
                        data_out <= 0;
                        done <= 0;
                    end
                end
                START_BIT: begin
                    data_out <= 0;
                    state <= DATA_BITS;
                end
                DATA_BITS: begin
                    data_out <= data_reg[bit_counter];
                    parity <= parity ^ data_reg[bit_counter];
                    if (bit_counter == BIT_COUNT - 1) begin
                        state <= PARITY_BIT;
                    end else begin
                        bit_counter <= bit_counter + 1;
                    end
                end
                PARITY_BIT: begin
                    data_out <= parity;
                    state <= STOP_BIT;
                end
                STOP_BIT: begin
                    data_out <= 1;
                    state <= DONE;
                end
                DONE: begin
                    data_out <= 1;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

