module key_filter(clk,rst_n,key_pin,key_status,key_event);
	input clk;
	input rst_n;
	input key_pin;
	output reg key_status;
	output reg key_event;
reg [2:0] key_edge;
	reg [3:0] key_cnt;
	reg [1:0] key_state;
	parameter idle = 0,press = 1,steady = 2,release = 3;
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_edge <= 3'b000;
			key_cnt <= 4'b0000;
			key_state <= idle;
		end
		else begin
			key_edge <= {key_edge[1:0],key_pin};
			case(key_state)
				idle:begin
					if(key_edge == 3'b001) begin
						key_cnt <= 4'b0000;
						key_state <= press;
					end
				end
				press:begin
					if(key_edge == 3'b011) begin
						key_cnt <= key_cnt + 1'b1;
						if(key_cnt == 4'b1111) begin
							key_state <= steady;
						end
					end
					else begin
						key_cnt <= 4'b0000;
						key_state <= idle;
					end
				end
				steady:begin
					if(key_edge == 3'b110) begin
						key_cnt <= 4'b0000;
						key_state <= release;
					end
				end
				release:begin
					if(key_edge == 3'b100) begin
						key_cnt <= key_cnt + 1'b1;
						if(key_cnt == 4'b1111) begin
							key_state <= idle;
						end
					end
					else begin
						key_cnt <= 4'b0000;
						key_state <= idle;
					end
				end
			endcase
		end
	end
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			key_status <= 1'b0;
			key_event <= 1'b0;
		end
		else begin
			case(key_state)
				idle:begin
					key_status <= 1'b0;
					key_event <= 1'b0;
				end
				press:begin
					key_status <= 1'b1;
					key_event <= 1'b0;
				end
				steady:begin
					key_status <= 1'b1;
					key_event <= 1'b0;
				end
				release:begin
					key_status <= 1'b0;
					key_event <= 1'b1;
				end
			endcase
		end
	end
endmodule

module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(*) begin
        case (alu_ctrl)
            4'b0000: result = x + y;
            4'b0001: result = x - y;
            4'b0010: result = x * y;
            4'b0011: result = x / y;
            4'b0100: result = x & y;
            4'b0101: result = x | y;
            4'b0110: result = x ^ y;
            4'b0111: result = x < y;
            default: result = 0;
        endcase
        zero = (result == 0);
    end
endmodule

