module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 0, SETUP = 1, ACCESS = 2;
    reg [1:0] state;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (Transfer) begin
                        state <= SETUP;
                    end
                end
                SETUP: begin
                    if (PREADY) begin
                        state <= ACCESS;
                    end
                end
                ACCESS: begin
                    if (PREADY) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            PSELx <= 0;
            PENABLE <= 0;
            PWRITE <= 0;
            PADDR <= 0;
            PWDATA <= 0;
        end else begin
            case (state)
                IDLE: begin
                    PSELx <= 0;
                    PENABLE <= 0;
                    PWRITE <= 0;
                    PADDR <= 0;
                    PWDATA <= 0;
                end
                SETUP: begin
                    PSELx <= 1;
                    PENABLE <= 0;
                    PWRITE <= Wr_Rd;
                    PADDR <= Address;
                    PWDATA <= write_data;
                end
                ACCESS: begin
                    PSELx <= 1;
                    PENABLE <= 1;
                    PWRITE <= Wr_Rd;
                    PADDR <= Address;
                    PWDATA <= write_data;
                    if (Wr_Rd == 0) begin
                        read_data <= PRDATA;
                    end
                end
            endcase
        end
    end
endmodule

