module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if(startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if(clear) begin
				colour <= 3'b000;
				clear <= 0;
			end
			else begin
				if(x == 160) begin
					x <= 0;
					y <= y + 1;
				end
				else begin
					x <= x + 1;
				end
				if(x == user_x && y == user_y) begin
					colour <= 3'b100;
				end
				else if(x == enemy_x && y == enemy_y) begin
					colour <= 3'b010;
				end
				else if(enem_grid[160*y + x] == 1) begin
					colour <= 3'b001;
				end
				else begin
					colour <= 3'b000;
				end
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency=100000000;
parameter [31:0] g_Initial_Reset_Time=100000000;
parameter [31:0] c_Initial_Reset_Clocks = (g_Initial_Reset_Time * g_Clock_Frequency) / 1000000;
reg r_RST = 1'b1;
reg [31:0] r_RST_Counter = 0;
  always @(posedge i_CLK) begin
    if((r_RST_Counter < c_Initial_Reset_Clocks)) begin
      r_RST_Counter <= r_RST_Counter + 1;
    end
    else begin
      r_RST <= 1'b0;
    end
  end
  assign o_RST = r_RST;
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [1:0] state;
reg [1:0] next_state;
reg [15:0] timeCount;
reg [15:0] timeoutCounter;
parameter standby = 2'b00;
parameter startMeasure = 2'b01;
parameter waitForPulse = 2'b10;
parameter countPulse = 2'b11;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= standby;
    end else begin
        state <= next_state;
    end
end
always @(state or do_measure or sonar_pulse) begin
    case (state)
        standby: begin
            if (do_measure) begin
                next_state = startMeasure;
            end else begin
                next_state = standby;
            end
        end
        startMeasure: begin
            if (sonar_pulse) begin
                next_state = waitForPulse;
            end else begin
                next_state = startMeasure;
            end
        end
        waitForPulse: begin
            if (sonar_pulse) begin
                next_state = countPulse;
            end else begin
                next_state = waitForPulse;
            end
        end
        countPulse: begin
            if (sonar_pulse) begin
                next_state = countPulse;
            end else begin
                next_state = standby;
            end
        end
        default: begin
            next_state = standby;
        end
    endcase
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        READY <= 0;
    end else begin
        READY <= (state == standby);
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        inches <= 0;
    end else begin
        inches <= (timeCount * 10) / 16;
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sonar_trigger <= 0;
    end else begin
        if (state == startMeasure) begin
            sonar_trigger <= 1;
        end else begin
            sonar_trigger <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeCount <= 0;
    end else begin
        if (state == countPulse) begin
            timeCount <= timeCount + 1;
        end else begin
            timeCount <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeoutCounter <= 0;
    end else begin
        if (state == standby) begin
            timeoutCounter <= 0;
        end else if (timeoutCounter == 10000) begin
            timeoutCounter <= 0;
        end else begin
            timeoutCounter <= timeoutCounter + 1;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= standby;
    end else begin
        state <= next_state;
    end
end
endmodule

