module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg       input_a_ack;

  reg       [1:0] state;
  reg       [63:0] value;
  reg       s_input_a_ack;

  reg       [31:0] file;
  reg       [31:0] file2;

  always @(posedge clk) begin
    if (rst) begin
      state <= 0;
      input_a_ack <= 0;
    end else begin
      case (state)
        0: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 1;
            input_a_ack <= 1;
          end
        end
        1: begin
          input_a_ack <= 0;
          file <= $fopena("resp_z");
          $fdisplay(file, "%d", value[63:32]);
          $fdisplay(file2, "%d", value[31:0]);
          $fclose(file);
          state <= 0;
        end
      endcase
    end
  end

endmodule

