module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    reg [7 : 0] mem [0 : 15];
    always @(posedge clock) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end
        else if (wrreq) begin
            mem[wp] <= data;
            if (wp == 15) begin
                wp <= 0;
                w_flag <= 1;
            end
            else begin
                wp <= wp + 1;
                w_flag <= 0;
            end
        end
    end
    always @(posedge clock) begin
        if (sclr) begin
            rp <= 0;
            r_flag <= 0;
        end
        else if (rdreq) begin
            if (rp == 15) begin
                rp <= 0;
                r_flag <= 1;
            end
            else begin
                rp <= rp + 1;
                r_flag <= 0;
            end
        end
    end
    always @(wp, rp, w_flag, r_flag) begin
        if (w_flag == 1 && r_flag == 1) begin
            full <= 1;
            empty <= 1;
        end
        else if (w_flag == 1) begin
            full <= 1;
            empty <= 0;
        end
        else if (r_flag == 1) begin
            full <= 0;
            empty <= 1;
        end
        else if (wp == rp) begin
            full <= 0;
            empty <= 0;
        end
        else if (wp > rp) begin
            full <= 0;
            empty <= 0;
        end
        else begin
            full <= 0;
            empty <= 0;
        end
    end
    always @(posedge clock) begin
        if (rdreq) begin
            q <= mem[rp];
        end
    end
endmodule

