module timer_variable(
input wire zedboard_clk,
input wire enable,
input wire reset,
output reg timerOutput
); 

reg [31:0] timer_value = 0;
  always @(posedge zedboard_clk, posedge reset) begin
    if((reset == 1'b1)) begin
      timer_value <= 0;
      timerOutput <= 1'b0;
    end else begin
      if((timer_value == 100000)) begin
        timer_value <= 0;
        timerOutput <= 1'b1;
      end
      else begin
        timer_value <= timer_value + 1;
        timerOutput <= 1'b0;
      end
    end
  end
endmodule

module NAND3xp33_ASAP7_75t_R (Y, A, B, C);
output Y;
input A, B, C;
wire A__bar, B__bar, C__bar;

	not (C__bar, C);
	not (B__bar, B);
	not (A__bar, A);
	or (Y, A__bar, B__bar, C__bar);


	specify
		(A => Y) = 0;
		(B => Y) = 0;
		(C => Y) = 0;
	endspecify
endmodule

module dffrl_async (din, clk, rst_l, q, se, si, so);

input   [SIZE-1:0]      din ;   
input                   clk ;   
input                   rst_l ;   

output  [SIZE-1:0]      q ;     

input                   se ;    
input   [SIZE-1:0]      si ;    
output  [SIZE-1:0]      so ;
parameter SIZE = 1;

reg     [SIZE-1:0]      q ;

always @ (posedge clk or negedge rst_l)
    if (!rst_l)
        q <= {SIZE{1'b0}};
    else
        q <= din;

assign so = q;

endmodule

module sr_latch(NQ, Q, S, R);
output Q, NQ;
input S, R;
reg state = 1;
assign #5 Q = state;
assign #5 NQ = ~state;
always @(S or R)
begin
	if(S == 1)
		state = 1;
	else if(R == 1)
		state = 0;
end
endmodule

module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    begin
        if (J & K)
            Q <= ~Q;
        else if (J)
            Q <= 1;
        else if (K)
            Q <= 0;
    end

    assign Qbar = ~Q;
endmodule

module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);
logic [12:0] rom_address;
logic [2:0] rom_q;

logic [3:0] palette_red, palette_green, palette_blue;

logic negedge_vga_clk;


assign negedge_vga_clk = ~vga_clk;







assign rom_address = (DrawX*60)/80 + (((DrawY*90)/160) * 60);

always_ff @ (posedge vga_clk) begin

	red <= 4'h0;
	green <= 4'h0;
	blue <= 4'h0;

	if (blank) begin
		red <= palette_red;
		green <= palette_green;
		blue <= palette_blue;
	end
end

Walk2_rom Walk2_rom (
	.clock   (negedge_vga_clk),
	.address (rom_address),
	.q       (rom_q)
);

Walk2_palette Walk2_palette (
	.index (rom_q),
	.red   (palette_red),
	.green (palette_green),
	.blue  (palette_blue)
);

endmodule

