module barrel_shifter_tb;
reg [7:0] in;
	reg [2:0] control;
	reg [7:0] expected;
	reg [7:0] out;
	reg [7:0] error;

	barrel_shifter uut(
		.in(in),
		.control(control),
		.out(out)
	);

	initial begin
		error = 0;
		in = 8'b10000000;
		control = 3'b000;
		expected = 8'b10000000;
		#10;
		if (out !== expected) begin
			error = error + 1;
			$display("FAIL: Expected %b, got %b", expected, out);
		end else begin
			$display("PASS");
		end

		in = 8'b10000000;
		control = 3'b001;
		expected = 8'b01000000;
		#10;
		if (out !== expected) begin
			error = error + 1;
			$display("FAIL: Expected %b, got %b", expected, out);
		end else begin
			$display("PASS");
		end

		in = 8'b10000000;
		control = 3'b010;
		expected = 8'b00100000;
		#10;
		if (out !== expected) begin
			error = error + 1;
			$display("FAIL: Expected %b, got %b", expected, out);
		end else begin
			$display("PASS");
		end

		in = 8'b10000000;
		control = 3'b011;
		expected = 8'b00010000;
		#10;
		if (out !== expected) begin
			error = error + 1;
			$display("FAIL: Expected %b, got %b", expected, out);
		end else begin
			$display("PASS");
		end

		in = 8'b11111111;
		control = 3'b111;
		expected = 8'b00000001;
		#10;
		if (out !== expected) begin
			error = error + 1;
			$display("FAIL: Expected %b, got %b", expected, out);
		end else begin
			$display("PASS");
		end

		if (error == 0) begin
			$display("All tests passed!");
		end else begin
			$display("Tests failed!");
		end
	end
endmodule

