module adder_sub(s, cout, a, b, cin, cnt, clk, rst);
	input cin, clk, rst;
	input cnt;
	input [n-1:0] a, b;
	output reg cout;
	output reg [n-1:0] s;
parameter n = 32;
	reg [n-1:0] ai, bi;
	reg ci;
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			s <= 0;
			cout <= 0;
		end else begin
			ai <= a;
			bi <= b;
			ci <= cin;
			if (cnt == 0) begin
				{cout, s} <= ai + bi + ci;
			end else begin
				{cout, s} <= ai - bi - ci;
			end
		end
	end
endmodule

module rca_16b(A, B, S, C_out);
    input [N-1: 0] A, B;
    output [N-1:0] S;
    output         C_out;
parameter N = 16;
    wire [N-1:0]   S;
    wire           C_out;
    genvar i;
    generate
        for (i = 0; i < N; i = i + 1) begin: gen_rca
            if (i == 0) begin
                full_adder fa0(A[i], B[i], 1'b0, S[i], C_out);
            end
            else begin
                full_adder fa1(A[i], B[i], S[i-1], S[i], C_out);
            end
        end
    endgenerate
endmodule

module delay (
	input clk,
	input reset,
	input [3:0] variable_pulse_index,
	output slow_pulse,
	output fast_pulse,
	output variable_pulse
);
reg [31:0] counter = 0;
	assign slow_pulse = (counter > 18000000);
	assign fast_pulse = (counter > 4800000);
	assign variable_pulse = (counter > (24000000 - (2000000 * variable_pulse_index / 15)));
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			counter <= 0;
		end else begin
			counter <= counter + 1;
		end
	end
endmodule

