module FSM_game(
input wire iRST,
input wire iCLK,
input wire [1:0] iA,
input wire [1:0] iB,
output wire oA,
output wire oB
); 

parameter [2:0]
  DRAW = 0,
  B_LEAD = 1,
  B_WIN = 2,
  A_LEAD = 3,
  A_WIN = 4;
reg [2:0] sSTATE;
reg [2:0] sNEXT_STATE;
wire [1:0] sWIN;
  always @(posedge iCLK, posedge iRST) begin
    if((iRST == 1'b1)) begin
      sSTATE <= DRAW;
    end else begin
      sSTATE <= sNEXT_STATE;
    end
  end
  always @(sSTATE, iA, iB) begin
    case(sSTATE)
    DRAW : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b01)) begin
        sNEXT_STATE <= DRAW;
      end
      else begin
        sNEXT_STATE <= DRAW;
      end
    end
    B_LEAD : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b01)) begin
        sNEXT_STATE <= B_WIN;
      end
      else begin
        sNEXT_STATE <= B_LEAD;
      end
    end
    B_WIN : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= B_WIN;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= B_WIN;
      end
      else if((iA == 2'b01 && iB == 2'b01)) begin
        sNEXT_STATE <= B_WIN;
      end
      else begin
        sNEXT_STATE <= B_WIN;
      end
    end
    A_LEAD : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= B_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= A_LEAD;
      end
      else if((iA == 2'b01 && iB == 2'b01)) begin
        sNEXT_STATE <= A_WIN;
      end
      else begin
        sNEXT_STATE <= A_LEAD;
      end
    end
    A_WIN : begin
      if((iA == 2'b00 && iB == 2'b00)) begin
        sNEXT_STATE <= DRAW;
      end
      else if((iA == 2'b00 && iB == 2'b01)) begin
        sNEXT_STATE <= A_WIN;
      end
      else if((iA == 2'b01 && iB == 2'b00)) begin
        sNEXT_STATE <= A_WIN;
      end
      else if((iA == 2'b01 && iB == 2'b01)) begin
        sNEXT_STATE <= A_WIN;
      end
      else begin
        sNEXT_STATE <= A_WIN;
      end
    end
    default : begin
      sNEXT_STATE <= DRAW;
    end
    endcase
  end
  assign sWIN = sSTATE[1:0];
  assign oA = sWIN[1];
  assign oB = sWIN[0];
endmodule

