module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 16;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = DAT_WIDTH * (2**SEL_WIDTH);

wire [DAT_WIDTH-1:0] tmp [0:TOTAL_DAT/DAT_WIDTH-1];

genvar i,j;
generate
	for (i=0; i<TOTAL_DAT/DAT_WIDTH; i=i+1) begin: gen1
		assign tmp[i] = din[i*DAT_WIDTH+DAT_WIDTH-1:i*DAT_WIDTH];
	end
	for (j=0; j<SEL_WIDTH; j=j+1) begin: gen2
		assign dout = tmp[sel[j]];
	end
endgenerate

endmodule

module nor2(
