module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );
reg [WIDTH-1:0] lfsr_r;
wire [WIDTH-1:0] lfsr_next;
wire feedback;
assign feedback = (lfsr_r & TAPS) | (lfsr_r & {WIDTH{1'b1}});
assign lfsr_next = {lfsr_r[WIDTH-2:0], feedback};
assign output_o = lfsr_r;
always @(posedge clk_i) begin
    if (rst_i) begin
        lfsr_r <= SEED;
    end else if (next_i) begin
        lfsr_r <= lfsr_next;
    end
end
endmodule

