begin
    case (y)
        6'b000001: Y2 = 0;
        6'b000010: Y2 = 1;
        6'b000100: Y2 = 0;
        6'b001000: Y2 = 1;
        6'b010000: Y2 = 0;
        6'b100000: Y2 = 1;
    endcase
    case (y)
        6'b000001: Y4 = 0;
        6'b000010: Y4 = 1;
        6'b000100: Y4 = 1;
        6'b001000: Y4 = 0;
        6'b010000: Y4 = 1;
        6'b100000: Y4 = 0;
    endcase
end
assign Y1 = Y2;
assign Y3 = Y4;
endmodule

module TopModule(
