module TopModule(
    input clk,
    input reset,
    input in,
    output out
);
parameter A = 1'b0;
    parameter B = 1'b1;
    reg state = B;
    always @(posedge clk) begin
        if (reset) begin
            state <= B;
        end else begin
            case (state)
                A: if (in) state <= A;
                B: if (!in) state <= A;
                default: state <= B;
            endcase
        end
    end
    assign out = state;
endmodule

