module TopModule(
    input clk,
    input reset,
    input [7:0] in,
    output done
);
reg [1:0] state;
    reg [2:0] count;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            count <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3]) begin
                        state <= 1;
                        count <= 0;
                    end
                end
                1: begin
                    if (in[3]) begin
                        state <= 2;
                        count <= 1;
                    end else begin
                        state <= 0;
                    end
                end
                2: begin
                    if (in[3]) begin
                        state <= 3;
                        count <= 2;
                    end else begin
                        state <= 1;
                    end
                end
                3: begin
                    if (in[3]) begin
                        state <= 0;
                        count <= 0;
                    end else begin
                        state <= 2;
                    end
                end
            endcase
        end
    end
    assign done = (state == 3);
endmodule

module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
);
reg [1:0] state;
    reg       z_reg;
    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= 2'b00;
            z_reg <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    if (x) begin
                        state <= 2'b01;
                        z_reg <= 1'b0;
                    end else begin
                        state <= 2'b00;
                        z_reg <= 1'b0;
                    end
                end
                2'b01: begin
                    if (x) begin
                        state <= 2'b10;
                        z_reg <= 1'b0;
                    end else begin
                        state <= 2'b00;
                        z_reg <= 1'b0;
                    end
                end
                2'b10: begin
                    if (x) begin
                        state <= 2'b11;
                        z_reg <= 1'b1;
                    end else begin
                        state <= 2'b00;
                        z_reg <= 1'b0;
                    end
                end
                2'b11: begin
                    if (x) begin
                        state <= 2'b11;
                        z_reg <= 1'b1;
                    end else begin
                        state <= 2'b00;
                        z_reg <= 1'b0;
                    end
                end
            endcase
        end
    end
    assign z = z_reg;
endmodule

