module TopModule(
    input clk,
    input in,
    input reset,
    output [7:0] out_byte,
    output done
);
reg [3:0] state;
    reg [7:0] byte;
    reg [2:0] bit_count;
    reg [7:0] out_byte_reg;
    reg done_reg;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            byte <= 0;
            bit_count <= 0;
            out_byte_reg <= 0;
            done_reg <= 0;
        end else begin
            case (state)
                0: begin
                    if (in == 0) begin
                        state <= 1;
                        bit_count <= 0;
                    end
                end
                1: begin
                    if (bit_count == 7) begin
                        state <= 2;
                    end else begin
                        bit_count <= bit_count + 1;
                    end
                end
                2: begin
                    if (in == 1) begin
                        state <= 3;
                    end else begin
                        state <= 0;
                    end
                end
                3: begin
                    state <= 0;
                    done_reg <= 1;
                end
            endcase
            if (state == 1) begin
                byte[bit_count] <= in;
            end
            if (state == 3) begin
                out_byte_reg <= byte;
            end
        end
    end
    assign out_byte = out_byte_reg;
    assign done = done_reg;
endmodule

