output q, state;
reg q, state;
always @(posedge clk) begin
    state <= q;
    q <= a & b;
end
endmodule

module TopModule(
    input clk,
    input resetn,
    input [2:0] r,
    output reg [2:0] g
);
reg [1:0] state, next_state;

always @(*) begin
    case (state)
        0: next_state = (r[0] == 0 && r[1] == 0 && r[2] == 0) ? 0 : (r[0] == 1) ? 1 : (r[1] == 1) ? 2 : 3;
        1: next_state = (r[0] == 1) ? 1 : 0;
        2: next_state = (r[1] == 1) ? 2 : 0;
        3: next_state = (r[0] == 0 && r[1] == 0 && r[2] == 0) ? 0 : (r[0] == 1) ? 1 : (r[1] == 1) ? 2 : 3;
    endcase
end

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        state <= 0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        0: g = 0;
        1: g = 3'b001;
        2: g = 3'b010;
        3: g = 3'b100;
    endcase
end

endmodule

