module TopModule(
    input wire clk,
    input wire areset,
    input wire bump_left,
    input wire bump_right,
    input wire ground,
    input wire dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
    );
reg falling;
    reg falling_last;
    reg digging_last;
    reg walk_left_last;
    reg walk_right_last;
    reg aaah_last;
    reg digging_last;
    always @(posedge clk) begin
        if (areset) begin
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
            falling <= 0;
            falling_last <= 0;
            digging_last <= 0;
            walk_left_last <= 1;
            walk_right_last <= 0;
            aaah_last <= 0;
            digging_last <= 0;
        end else begin
            falling_last <= falling;
            digging_last <= digging;
            walk_left_last <= walk_left;
            walk_right_last <= walk_right;
            aaah_last <= aaah;
            digging_last <= digging;
            if (ground == 0) begin
                falling <= 1;
                aaah <= 1;
                walk_left <= 0;
                walk_right <= 0;
            end else begin
                falling <= 0;
                aaah <= 0;
                if (dig == 1) begin
                    digging <= 1;
                end else begin
                    digging <= 0;
                end
            end
            if (falling_last == 0) begin
                if (digging_last == 0) begin
                    if (bump_left == 1) begin
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (bump_right == 1) begin
                        walk_left <= 1;
                        walk_right <= 0;
                    end
                end
            end
            if (falling == 0) begin
                if (digging_last == 0) begin
                    if (bump_left == 1) begin
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (bump_right == 1) begin
                        walk_left <= 1;
                        walk_right <= 0;
                    end
                end
            end
        end
    end
endmodule

module TopModule(
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
wire [6:0] predict_index;
    wire [6:0] train_index;

    assign predict_index = predict_pc ^ predict_history;
    assign train_index = train_pc ^ train_history;

    wire [1:0] predict_counter;
    wire [1:0] train_counter;

    wire [6:0] predict_next_history;
    wire [6:0] train_next_history;

    SaturatingCounter #(
        .WIDTH(2)
    ) predict_counter_inst(
        .clk(clk),
        .reset(areset),
        .increment(predict_valid),
        .decrement(predict_mispredicted),
        .counter(predict_counter)
    );

    SaturatingCounter #(
        .WIDTH(2)
    ) train_counter_inst(
        .clk(clk),
        .reset(areset),
        .increment(train_valid),
        .decrement(train_mispredicted),
        .counter(train_counter)
    );

    wire [6:0] predict_next_history;
    wire [6:0] train_next_history;

    assign predict_next_history = predict_history ^ {predict_counter[1], predict_counter[0]};
    assign train_next_history = train_history ^ {train_counter[1], train_counter[0]};

    wire [127:0] pht;

    assign predict_taken = pht[predict_index];
    assign predict_history = predict_next_history;

    assign pht[predict_index] = predict_counter;
    assign pht[train_index] = train_counter;

    always @(posedge clk) begin
        if (train_valid) begin
            if (train_mispredicted) begin
                predict_history <= train_next_history;
            end
        end
    end

endmodule

