module TopModule (
  input clk,
  input j,
  input k,
  input areset,
  output out
);
parameter OFF = 1'b0;
  parameter ON = 1'b1;
  reg state;
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= OFF;
    end else begin
      case (state)
        OFF: begin
          if (j) begin
            state <= ON;
          end
        end
        ON: begin
          if (k) begin
            state <= OFF;
          end
        end
      endcase
    end
  end
  assign out = state;
endmodule

