        3'b001: begin
          y <= x ? 3'b100 : 3'b001;
          z <= 1'b0;
        end
        3'b010: begin
          y <= x ? 3'b001 : 3'b010;
          z <= 1'b0;
        end
        3'b011: begin
          y <= x ? 3'b010 : 3'b001;
          z <= 1'b1;
        end
        3'b100: begin
          y <= x ? 3'b100 : 3'b011;
