module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);
reg [1:0] state, next_state;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      state <= 0;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      0: begin
        if (x) begin
          next_state = 1;
        end else begin
          next_state = 0;
        end
      end
      1: begin
        if (x) begin
          next_state = 2;
        end else begin
          next_state = 0;
        end
      end
      2: begin
        if (x) begin
          next_state = 2;
        end else begin
          next_state = 0;
        end
      end
      default: begin
        next_state = 0;
      end
    endcase
  end

  always @(*) begin
    case (state)
      0: z = 0;
      1: z = 0;
      2: z = 1;
      default: z = 0;
    endcase
  end

endmodule

module TopModule (
  input [3:0] a,
  input [3:0] b,
  input [3:0] c,
  input [3:0] d,
  input [3:0] e,
  output reg [3:0] q
);
always @* begin
    case (c)
      0: q = b;
      1: q = e;
      2: q = a;
      3: q = d;
      4: q = 4'hf;
      5: q = 4'hf;
      6: q = 4'hf;
      7: q = 4'hf;
      8: q = 4'hf;
      9: q = 4'hf;
      10: q = 4'hf;
      11: q = 4'hf;
      12: q = 4'hf;
      13: q = 4'hf;
      14: q = 4'hf;
      15: q = 4'hf;
    endcase
  end
endmodule

module TopModule (
  input x,
  input y,
  output z
);
A a1 (x, y, a1_z);
  A a2 (x, y, a2_z);
  B b1 (x, y, b1_z);
  B b2 (x, y, b2_z);
  or or1 (a1_z, b1_z, or1_z);
  and and1 (a2_z, b2_z, and1_z);
  xor xor1 (or1_z, and1_z, z);
endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);
always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1;
  end

  always @(*) begin
    if (~arrived)
      keep_driving = ~gas_tank_empty;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input s,
  input w,
  output reg z
);
reg [1:0] state;
  localparam A = 0, B = 1;
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
      z <= 0;
    end else begin
      case (state)
        A: begin
          if (s) begin
            state <= B;
            z <= 0;
          end
        end
        B: begin
          if (w) begin
            state <= B;
            z <= 0;
          end else begin
            state <= A;
            z <= 1;
          end
        end
      endcase
    end
  end
endmodule

module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);
reg [2:0] Y;
  always @(posedge clk) begin
    Y <= (x == 0) ? y : Y;
    Y0 <= Y[0];
    z <= Y[2];
  end
endmodule

module TopModule (
  input [2:0] y,
  input w,
  output reg Y1
);
always @(*) begin
    case (y[2:0])
      3'b000: Y1 = 1'b0;
      3'b001: Y1 = 1'b0;
      3'b010: Y1 = 1'b0;
      3'b011: Y1 = 1'b1;
      3'b100: Y1 = 1'b0;
      3'b101: Y1 = 1'b1;
    endcase
  end
endmodule

module TopModule (
  input clk,
  input reset,
  input w,
  output z
);
reg A, B, C, D, E, F;
  always @(posedge clk) begin
    if (reset) begin
      A <= 0;
      B <= 0;
      C <= 0;
      D <= 0;
      E <= 0;
      F <= 0;
    end else begin
      case ({A, w})
        2'b00: A <= 0;
        2'b01: A <= 1;
        2'b10: B <= 0;
        2'b11: D <= 1;
      endcase
      case ({B, w})
        2'b00: C <= 0;
        2'b01: D <= 1;
        2'b10: F <= 0;
        2'b11: A <= 1;
      endcase
      case ({C, w})
        2'b00: E <= 1;
        2'b01: D <= 1;
        2'b10: C <= 0;
        2'b11: D <= 1;
      endcase
      case ({D, w})
        2'b00: F <= 0;
        2'b01: A <= 1;
        2'b10: C <= 0;
        2'b11: D <= 1;
      endcase
      case ({E, w})
        2'b00: E <= 1;
        2'b01: D <= 1;
        2'b10: C <= 0;
        2'b11: D <= 1;
      endcase
      case ({F, w})
        2'b00: C <= 0;
        2'b01: D <= 1;
        2'b10: C <= 0;
        2'b11: D <= 1;
      endcase
    end
  end
  assign z = A;
endmodule

