module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);
always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q <= next(q);
    end
  end

  function [255:0] next(input [255:0] q);
    integer i, j;
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        next[i*16 + j] = nextCell(q, i, j);
      end
    end
  endfunction

  function [0:0] nextCell(input [255:0] q, integer i, integer j);
    integer n;
    n = countNeighbours(q, i, j);
    if (n == 0 || n == 1) begin
      nextCell = 0;
    end else if (n == 2) begin
      nextCell = q[i*16 + j];
    end else if (n == 3) begin
      nextCell = 1;
    end else begin
      nextCell = 0;
    end
  endfunction

  function [0:0] countNeighbours(input [255:0] q, integer i, integer j);
    integer n;
    n = 0;
    n = n + q[toroid(i-1, j-1)];
    n = n + q[toroid(i-1, j)];
    n = n + q[toroid(i-1, j+1)];
    n = n + q[toroid(i, j-1)];
    n = n + q[toroid(i, j+1)];
    n = n + q[toroid(i+1, j-1)];
    n = n + q[toroid(i+1, j)];
    n = n + q[toroid(i+1, j+1)];
    countNeighbours = n;
  endfunction

  function [0:0] toroid(input [0:0] i, input [0:0] j);
    toroid = q[toroidIndex(i, j)];
  endfunction

  function [4:0] toroidIndex(input [0:0] i, input [0:0] j);
    toroidIndex = ((i + 16) % 16) * 16 + ((j + 16) % 16);
  endfunction

endmodule

