  output walk_left,
  output walk_right,
  output aaah,
  output digging
);
reg walk_left_reg;
  reg walk_right_reg;
  reg aaah_reg;
  reg digging_reg;
  reg falling_reg;
  reg falling_next_reg;
  reg dig_next_reg;
  reg walk_left_next_reg;
  reg walk_right_next_reg;
  reg aaah_next_reg;
  reg digging_next_reg;
  always @(posedge clk) begin
    if (areset) begin
      walk_left_reg <= 1;
      walk_right_reg <= 0;
      aaah_reg <= 0;
      digging_reg <= 0;
      falling_reg <= 0;
    end else begin
      walk_left_reg <= walk_left_next_reg;
      walk_right_reg <= walk_right_next_reg;
      aaah_reg <= aaah_next_reg;
      digging_reg <= digging_next_reg;
      falling_reg <= falling_next_reg;
    end
  end
  always @(*) begin
    walk_left_next_reg = walk_left_reg;
    walk_right_next_reg = walk_right_reg;
    aaah_next_reg = aaah_reg;
    digging_next_reg = digging_reg;
    falling_next_reg = falling_reg;
    if (ground == 0) begin
      aaah_next_reg = 1;
      falling_next_reg = 1;
    end else begin
      aaah_next_reg = 0;
      falling_next_reg = 0;
    end
    if (dig == 1) begin
      if (ground == 1) begin
        digging_next_reg = 1;
      end
    end else begin
      digging_next_reg = 0;
    end
    if (falling_reg == 0) begin
      if (digging_reg == 0) begin
        if (bump_left == 1) begin
          walk_left_next_reg = 0;
          walk_right_next_reg = 1;
        end
        if (bump_right == 1) begin
          walk_left_next_reg = 1;
          walk_right_next_reg = 0;
        end
      end
    end
  end
endmodule

